\title{An Exact Geometric Conjugacy Between the Logistic Map and the Tent Map}
\author{Aristotle}
\date{\today}

\begin{document}
\begin{abstract}
The logistic map $f(x) = 4x(1-x)$ on the unit interval is the archetypal smooth
one-dimensional chaotic system and the computational core of many
``chaos-based'' stream ciphers. The tent map $T(t) = 1 - |2t-1|$ is its
piecewise-linear cousin. We establish that these two systems, though
superficially unrelated, are \emph{dynamically identical}: they are
topologically conjugate through the single strictly increasing homeomorphism
$h(t) = \sin^2(\pi t/2)$ of $[0,1]$. Our central result is the exact intertwining
identity $f(h(t)) = h(T(t))$, valid for every real $t$, from which we derive that
$f^n(h(t)) = h(T^n(t))$ for all $n$, that $h$ is a bijection of the unit
interval, and that fixed points and periodic orbits transfer verbatim between the
two maps. As concrete corollaries we recover the logistic fixed point $3/4$ from
the tent fixed point $2/3$, and construct a genuine period-two logistic orbit
from the tent cycle $2/5 \leftrightarrow 4/5$. We discuss the consequence for
chaos-based cryptography: because the conjugacy is exact and invertible, any
invariant computable from a logistic keystream has an exact tent-map counterpart,
so the smooth cipher is no stronger than its transparent piecewise-linear shadow.
\end{abstract}

\maketitle

\section{Introduction}

Chaotic dynamical systems are prized for two properties that make them tempting
building blocks for pseudorandomness: \emph{sensitive dependence on initial
conditions}, whereby nearby trajectories diverge exponentially, and
\emph{topological mixing}, whereby orbits spread densely over the state space.
The logistic map at its fully chaotic parameter,
\[
  f(x) = 4x(1-x), \qquad x \in [0,1],
\]
exhibits both, with Lyapunov exponent $\lambda = \log 2$: on average, distances
double at every step. This has motivated a large literature on ``chaos
ciphers,'' which mask a plaintext with the orbit of a secret seed under $f$.

The tent map,
\[
  T(t) = 1 - |2t - 1|, \qquad t \in [0,1],
\]
is a piecewise-linear system with the same Lyapunov exponent $\log 2$. Its
analysis is elementary because it is built from two line segments, and it is
essentially the binary shift map in disguise.

The purpose of this paper is to make precise, and fully rigorous, the classical
folklore that these two maps are ``the same.'' We exhibit an explicit
\emph{topological conjugacy} --- a homeomorphism $h$ of the interval satisfying
$f \circ h = h \circ T$ --- implemented by a single smooth, monotone
reparametrization. The consequence is that every dynamical feature of one map is,
verbatim, a feature of the other. In particular, the celebrated smooth complexity
of the logistic map is revealed as a coordinate artifact of the elementary
combinatorics of folding straight lines.

\subsection*{Contributions}
\begin{enumerate}
  \item The intertwining identity (Theorem~\ref{thm:conj}):
        $f(h(t)) = h(T(t))$ for all real $t$, with $h(t) = \sin^2(\pi t/2)$.
  \item Iterated conjugacy (Theorem~\ref{thm:iter}):
        $f^n(h(t)) = h(T^n(t))$ for all $n \ge 0$.
  \item $h$ is a homeomorphism of $[0,1]$ (Theorem~\ref{thm:homeo}).
  \item Transfer of fixed and periodic points (Section~\ref{sec:transfer}).
  \item A cryptographic consequence (Section~\ref{sec:crypto}).
\end{enumerate}

\section{Definitions and preliminaries}

Throughout, $I = [0,1]$ denotes the closed unit interval.

\begin{definition}[Logistic map]
$f : \R \to \R$, $\ f(x) = 4x(1-x)$.
\end{definition}

\begin{definition}[Tent map]
$T : \R \to \R$, $\ T(t) = 1 - |2t - 1|$. Equivalently $T(t) = 2t$ for
$t \le 1/2$ and $T(t) = 2 - 2t$ for $t \ge 1/2$.
\end{definition}

\begin{definition}[Change of coordinates]
$h : \R \to \R$, $\ h(t) = \sin^2\!\big(\tfrac{\pi t}{2}\big)$.
\end{definition}

\begin{definition}[Topological conjugacy]
Two continuous self-maps $g_1 : X \to X$ and $g_2 : Y \to Y$ are
\emph{topologically conjugate} if there is a homeomorphism $\phi : Y \to X$ with
$g_1 \circ \phi = \phi \circ g_2$. Conjugacy is an equivalence relation that
preserves all dynamical invariants.
\end{definition}

\begin{lemma}[Invariance of the interval]\label{lem:inv}
Each of $f$, $T$, and $h$ maps $I$ into $I$.
\end{lemma}
\begin{proof}
For $x \in I$, $f(x) = 4x(1-x) \ge 0$ and $1 - f(x) = (2x-1)^2 \ge 0$, so
$f(x) \in I$. For $t \in I$, $|2t-1| \le 1$, so $T(t) = 1 - |2t-1| \in I$. For
$h$, $0 \le \sin^2\theta \le 1$ for all real $\theta$.
\end{proof}

\begin{lemma}[Endpoints]\label{lem:end}
$h(0) = 0$, $h(1) = 1$, and $f(0) = f(1) = 0$.
\end{lemma}
\begin{proof}
$h(0) = \sin^2 0 = 0$, $h(1) = \sin^2(\pi/2) = 1$; direct substitution gives
$f(0) = f(1) = 0$.
\end{proof}

\section{The intertwining identity}

\begin{theorem}[Conjugacy]\label{thm:conj}
For every real $t$, \ $f\big(h(t)\big) = h\big(T(t)\big).$
\end{theorem}
\begin{proof}
Write $\theta = \pi t/2$. Using $\cos^2\theta = 1 - \sin^2\theta$ and
$\sin(2\theta) = 2\sin\theta\cos\theta$,
\[
  f(h(t)) = 4\sin^2\theta(1 - \sin^2\theta) = 4\sin^2\theta\cos^2\theta
  = \sin^2(2\theta) = \sin^2(\pi t).
\]
For the right side, $h(T(t)) = \sin^2\!\big(\tfrac{\pi}{2}T(t)\big)$; split at
the fold.

\emph{Near branch} ($2t-1 \le 0$): $T(t) = 2t$, so $h(T(t)) = \sin^2(\pi t)$.

\emph{Far branch} ($2t-1 > 0$): $T(t) = 2 - 2t$, so
$h(T(t)) = \sin^2(\pi - \pi t) = \sin^2(\pi t)$, using
$\sin(\pi - \alpha) = \sin\alpha$.

In both cases $h(T(t)) = \sin^2(\pi t) = f(h(t))$.
\end{proof}

\begin{theorem}[Iterated conjugacy]\label{thm:iter}
For every $n \in \N$ and every real $t$, \ $f^{\,n}\big(h(t)\big) =
h\big(T^{\,n}(t)\big).$
\end{theorem}
\begin{proof}
Induction on $n$. The base case $n = 0$ is trivial. Assuming the claim for $k$,
\[
  f^{\,k+1}(h(t)) = f\big(f^{\,k}(h(t))\big) = f\big(h(T^{\,k}(t))\big)
  = h\big(T(T^{\,k}(t))\big) = h\big(T^{\,k+1}(t)\big),
\]
by the inductive hypothesis and Theorem~\ref{thm:conj}.
\end{proof}

\section{The change of coordinates is a homeomorphism}

\begin{theorem}[Strict monotonicity]\label{thm:mono}
$h$ is strictly increasing on $I$.
\end{theorem}
\begin{proof}
Let $0 \le a < b \le 1$. Then $\pi a/2, \pi b/2 \in [0,\pi/2]$ with
$\pi a/2 < \pi b/2$. Since $\sin$ is strictly increasing on $[-\pi/2,\pi/2]$,
$0 \le \sin(\pi a/2) < \sin(\pi b/2)$, and squaring a strictly increasing chain
of nonnegatives preserves strictness, so $h(a) < h(b)$.
\end{proof}

\begin{theorem}[Continuity and surjectivity]\label{thm:surj}
$h$ is continuous and maps $I$ onto $I$.
\end{theorem}
\begin{proof}
$h$ is a composition of continuous functions. By Lemma~\ref{lem:end},
$h(0)=0$ and $h(1)=1$; the intermediate value theorem gives $h(I) \supseteq I$,
and Lemma~\ref{lem:inv} gives $h(I) \subseteq I$.
\end{proof}

\begin{theorem}[$h$ is a homeomorphism of $I$]\label{thm:homeo}
$h$ restricts to a strictly increasing continuous bijection of $I$ onto itself,
with continuous inverse $h^{-1}(x) = \tfrac{2}{\pi}\arcsin\sqrt{x}$. Consequently
$f|_I$ and $T|_I$ are topologically conjugate.
\end{theorem}
\begin{proof}
Theorem~\ref{thm:mono} gives injectivity; Theorem~\ref{thm:surj} gives
continuity and surjectivity. A strictly monotone continuous bijection of a
compact interval has a continuous monotone inverse; solving
$x = \sin^2(\pi t/2)$ yields $t = \tfrac{2}{\pi}\arcsin\sqrt{x}$. With $h$ a
homeomorphism and $f\circ h = h \circ T$, the maps are conjugate.
\end{proof}

\section{Transfer of fixed and periodic points}\label{sec:transfer}

\begin{theorem}[Tent fixed points]\label{thm:tentfix}
$T(t) = t$ iff $t \in \{0, 2/3\}$.
\end{theorem}
\begin{proof}
On the near branch $2t = t \iff t = 0$; on the far branch
$2 - 2t = t \iff t = 2/3$. Both solutions lie in their respective branches.
\end{proof}

\begin{lemma}\label{lem:h23}
$h(2/3) = 3/4$.
\end{lemma}
\begin{proof}
$h(2/3) = \sin^2(\pi/3) = (\sqrt3/2)^2 = 3/4$.
\end{proof}

\begin{theorem}[Logistic fixed point by transport]\label{thm:logfix}
$f(3/4) = 3/4$.
\end{theorem}
\begin{proof}
By Theorem~\ref{thm:tentfix}, $T(2/3) = 2/3$. By Theorem~\ref{thm:conj} at
$t = 2/3$ and Lemma~\ref{lem:h23},
$f(3/4) = f(h(2/3)) = h(T(2/3)) = h(2/3) = 3/4$.
\end{proof}

\begin{theorem}[Transfer of periodic seeds]\label{thm:pertrans}
If $T^n(t) = t$, then $f^n(h(t)) = h(t)$.
\end{theorem}
\begin{proof}
By Theorem~\ref{thm:iter}, $f^n(h(t)) = h(T^n(t)) = h(t)$.
\end{proof}

\begin{lemma}[A tent 2-cycle]\label{lem:tent2}
$T(2/5) = 4/5$ and $T^2(2/5) = 2/5$.
\end{lemma}
\begin{proof}
$T(2/5) = 1 - |4/5 - 1| = 4/5$; $T(4/5) = 1 - |8/5 - 1| = 2/5$.
\end{proof}

\begin{theorem}[A genuine logistic period-two orbit]\label{thm:log2}
There exists $x \in I$ with $f^2(x) = x$ and $f(x) \ne x$; explicitly
$x = h(2/5) = \sin^2(\pi/5)$.
\end{theorem}
\begin{proof}
Set $x = h(2/5)$. By Lemma~\ref{lem:tent2} and Theorem~\ref{thm:iter},
$f^2(x) = h(T^2(2/5)) = h(2/5) = x$. If $f(x) = x$, then by
Theorem~\ref{thm:conj}, $h(4/5) = h(T(2/5)) = f(h(2/5)) = x = h(2/5)$; injectivity
of $h$ forces $2/5 = 4/5$, a contradiction. Hence $x$ has exact period two.
\end{proof}

Numerically $x = \sin^2(\pi/5) \approx 0.345492$ and
$f(x) = \sin^2(2\pi/5) \approx 0.904508$.

\section{Consequences for chaos-based cryptography}\label{sec:crypto}

A chaos cipher fixes a secret seed $x_0 \in (0,1)$ and emits the keystream
$x_0, f(x_0), f^2(x_0), \dots$ to mask a message. The design intuition is that
the smooth, transcendental structure of $f$ --- the $n$-th iterate $f^n$ is a
polynomial of degree $2^n$ --- makes seed recovery and prediction hard.

The conjugacy refutes this structurally. With
$t_0 = h^{-1}(x_0) = \tfrac{2}{\pi}\arcsin\sqrt{x_0}$, Theorem~\ref{thm:iter}
gives
\[
  x_k = f^k(x_0) = h\big(T^k(t_0)\big), \qquad k = 0,1,2,\dots
\]
Thus the logistic keystream is the tent keystream viewed through the fixed,
publicly known bijection $h$. Since $h, h^{-1}$ are explicit and efficiently
computable, an attacker converts freely between representations. Any exploitable
statistic has an exact tent-map counterpart under $h^{-1}$, and the tent map is
(up to reflection) the binary shift, so seed recovery is trivial.

\begin{principle}
Apparent analytic complexity is not cryptographic strength. A smooth chaotic
keystream that is topologically conjugate, by a computable homeomorphism, to a
piecewise-linear model inherits exactly the security of that model --- here,
essentially none.
\end{principle}

\section{Invariant measure: the arcsine law}

The tent map preserves Lebesgue measure on $I$. Pushing it forward through $h$
via $x = \sin^2(\pi t/2)$, with $dx = \tfrac{\pi}{2}\sin(\pi t)\,dt$ and
$\sin(\pi t) = 2\sqrt{x(1-x)}$, yields the logistic invariant density
\[
  \rho(x) = \frac{1}{\pi\sqrt{x(1-x)}}, \qquad x \in (0,1),
\]
the \emph{arcsine law}. The concentration of logistic orbits near the endpoints
is the image of the flat tent density under $h$.

\section{Discussion and future work}

The conjugacy welds smooth interval dynamics to the combinatorics of the folding
map through a single monotone reparametrization. Extensions include: an exact
$2^n$ count of period-$n$ points inherited from the sawtooth $T^n$; density of
periodic points and topological transitivity (hence Devaney chaos) transferred
from the tent map; rigorous derivation of the arcsine law as a pushforward; and a
general statement that every attacker-computable invariant of a logistic
keystream has an exact tent counterpart.

\section{Conclusion}

The smooth logistic map $f(x) = 4x(1-x)$ and the piecewise-linear tent map
$T(t) = 1 - |2t-1|$ are the same dynamical system in different coordinates, welded
by the strictly increasing homeomorphism $h(t) = \sin^2(\pi t/2)$ through the exact
identity $f \circ h = h \circ T$. Fixed points, periodic orbits, and all iterates
transfer verbatim. The curvature of the parabola is a coordinate illusion; the
engine of chaos is a single fold, worn openly by the tent and hidden by the
logistic map.

\end{document}

