import math
from typing import Callable

def logistic(x: float) -> float:
    return 4.0 * x * (1.0 - x)

def tent(t: float) -> float:
    return 1.0 - abs(2.0 * t - 1.0)

def h(t: float) -> float:
    return math.sin(math.pi * t / 2.0) ** 2

def verify_conjugacy(num_points: int = 20) -> float:
    """Check f(h(t)) = h(T(t)) on a grid; return the maximum absolute error."""
    max_err = 0.0
    for i in range(num_points + 1):
        t = i / num_points
        max_err = max(max_err, abs(logistic(h(t)) - h(tent(t))))
    return max_err

if __name__ == "__main__":
    print("max |f(h(t)) - h(T(t))| =", verify_conjugacy())

