def iterate(f: Callable[[float], float], x0: float, n: int) -> float:
    x = x0
    for _ in range(n):
        x = f(x)
    return x

def verify_iterated(t0: float = 0.137, n_max: int = 15) -> List[float]:
    """Return the per-step error |f^n(h(t0)) - h(T^n(t0))| for n = 0..n_max."""
    return [abs(iterate(logistic, h(t0), n) - h(iterate(tent, t0, n)))
            for n in range(n_max + 1)]

if __name__ == "__main__":
    for n, e in enumerate(verify_iterated()):
        print(f"n={n:2d}  error={e:.2e}")

import math
from typing import List

def logistic(x: float) -> float:
    return 4.0 * x * (1.0 - x)

def tent(t: float) -> float:
    return 1.0 - abs(2.0 * t - 1.0)

def h_inverse(x: float) -> float:
    return (2.0 / math.pi) * math.asin(math.sqrt(x))

def break_chaos_cipher(secret_seed: float = 0.7182818, m: int = 24) -> float:
    """Observe a logistic keystream, transport to the tent shadow via h^{-1},
    and confirm it is a genuine tent orbit (t_{k+1} = T(t_k)). Returns the
    maximum step error, which is ~1e-15: the cipher has no hidden strength."""
    keystream: List[float] = [secret_seed]
    x = secret_seed
    for _ in range(m):
        x = logistic(x)
        keystream.append(x)
    shadow = [h_inverse(v) for v in keystream]
    return max(abs(tent(shadow[k]) - shadow[k + 1]) for k in range(m))

if __name__ == "__main__":
    print("max |T(t_k) - t_{k+1}| =", break_chaos_cipher())

