def tent(t: float) -> float:
    return 1.0 - abs(2.0 * t - 1.0)

def h(t: float) -> float:
    return math.sin(math.pi * t / 2.0) ** 2

def logistic_orbit_via_tent(t0: float, n: int) -> List[float]:
    """Compute the length-(n+1) logistic orbit of the point h(t0) by iterating
    the *tent* map and transporting through h. By the conjugacy this equals the
    orbit computed by iterating the logistic map directly, but avoids the
    numerically ill-conditioned repeated multiplication near the endpoints."""
    orbit: List[float] = []
    t = t0
    for _ in range(n + 1):
        orbit.append(h(t))
        t = tent(t)
    return orbit

