import math
from typing import List

def logistic(x: float) -> float:
    return 4.0 * x * (1.0 - x)

def empirical_density(seed: float, n: int, bins: int) -> List[float]:
    """Iterate the logistic map n times from a generic seed and return the
    normalized histogram of visited states. Converges to the arcsine density
    rho(x) = 1/(pi sqrt(x(1-x))), the pushforward under h of the tent map's
    uniform invariant measure."""
    counts = [0] * bins
    x = seed
    for _ in range(n):
        x = logistic(x)
        counts[min(int(x * bins), bins - 1)] += 1
    return [c / n * bins for c in counts]

def arcsine_density(x: float) -> float:
    return 1.0 / (math.pi * math.sqrt(x * (1.0 - x)))
